create extension if not exists pgcrypto;
create table if not exists public.schools(id uuid primary key default gen_random_uuid(),name text not null,email text,max_students int not null default 500 check(max_students>0),subscription_status text not null default 'pending' check(subscription_status in ('pending','active','suspended','expired')),duration_unit text not null default 'month' check(duration_unit in ('day','month','lifetime')),duration_value int,starts_at timestamptz,expires_at timestamptz,approved_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text not null unique,full_name text not null default '',role text not null default 'pending' check(role in ('super_admin','school_admin','teacher','staff','pending')),school_id uuid references public.schools(id),approved boolean not null default false,created_at timestamptz not null default now());
create or replace function public.northstar_create_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email,full_name,role,approved) values(new.id,lower(new.email),coalesce(new.raw_user_meta_data->>'full_name',''),'pending',false) on conflict(id) do nothing;return new;end $$;
drop trigger if exists northstar_new_user on auth.users;create trigger northstar_new_user after insert on auth.users for each row execute function public.northstar_create_profile();
insert into public.profiles(id,email,full_name,role,approved) select id,lower(email),coalesce(raw_user_meta_data->>'full_name',''),'pending',false from auth.users on conflict(id) do nothing;
create or replace function public.northstar_super_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role='super_admin' and approved=true)$$;
create or replace function public.northstar_school_id() returns uuid language sql stable security definer set search_path=public as $$select p.school_id from public.profiles p join public.schools s on s.id=p.school_id where p.id=auth.uid() and p.approved=true and s.subscription_status='active' and (s.expires_at is null or s.expires_at>now())$$;
create table if not exists public.pending_invitations(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,email text not null,full_name text not null,role text not null default 'school_admin' check(role in ('school_admin','teacher','staff')),status text not null default 'draft' check(status in ('draft','invited','accepted','cancelled')),auth_user_id uuid references auth.users(id),created_at timestamptz not null default now(),invited_at timestamptz,accepted_at timestamptz,unique(school_id,email));
create table if not exists public.approval_requests(id uuid primary key default gen_random_uuid(),school_id uuid references public.schools(id) on delete cascade,requester_id uuid references auth.users(id),request_type text not null,status text not null default 'pending' check(status in ('pending','approved','rejected')),reviewed_by uuid references auth.users(id),reviewed_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.students(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,admission_no text not null,full_name text not null,class_name text,section text,guardian_name text,guardian_phone text,created_at timestamptz not null default now(),unique(school_id,admission_no));
create table if not exists public.staff(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,full_name text not null,email text,designation text,created_at timestamptz not null default now());
create table if not exists public.attendance(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,student_id uuid not null references public.students(id) on delete cascade,attendance_date date not null default current_date,status text not null check(status in ('present','absent','late','leave')),unique(student_id,attendance_date));
create table if not exists public.fee_records(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,student_id uuid references public.students(id) on delete set null,amount numeric(12,2) not null default 0,status text not null default 'unpaid',due_date date,created_at timestamptz not null default now());
-- Enforce student caps atomically for direct client inserts too.
create or replace function public.northstar_student_limit() returns trigger language plpgsql security definer set search_path=public as $$declare cap int;count_students int;begin select max_students into cap from public.schools where id=new.school_id for update;if cap is null then raise exception 'School not found';end if;select count(*) into count_students from public.students where school_id=new.school_id and (tg_op='INSERT' or id<>new.id);if count_students>=cap then raise exception 'School student limit reached';end if;return new;end $$;
drop trigger if exists enforce_northstar_student_limit on public.students;create trigger enforce_northstar_student_limit before insert or update of school_id on public.students for each row execute function public.northstar_student_limit();
alter table public.schools enable row level security;alter table public.profiles enable row level security;alter table public.pending_invitations enable row level security;alter table public.approval_requests enable row level security;
drop policy if exists schools_read on public.schools;create policy schools_read on public.schools for select to authenticated using(public.northstar_super_admin() or id=public.northstar_school_id());
drop policy if exists profiles_read on public.profiles;create policy profiles_read on public.profiles for select to authenticated using(id=auth.uid() or public.northstar_super_admin());
drop policy if exists invites_read on public.pending_invitations;create policy invites_read on public.pending_invitations for select to authenticated using(public.northstar_super_admin());
drop policy if exists approvals_read on public.approval_requests;create policy approvals_read on public.approval_requests for select to authenticated using(public.northstar_super_admin());
do $$declare t text;begin foreach t in array array['students','staff','attendance','fee_records'] loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists tenant_access on public.%I',t);execute format('create policy tenant_access on public.%I for all to authenticated using(school_id=public.northstar_school_id()) with check(school_id=public.northstar_school_id())',t);end loop;end $$;
